		const options = {
			body,
			jar: mocks.users[user].jar,
		};

		if (method !== 'get') {
			options.headers = {
				'x-csrf-token': mocks.users[user].csrf,
			};
		}

		return request[method](`${nconf.get('url')}/api/v3${path}`, options);
	};

